});

const contactMatches = contactos
  .filter(c => norm(c.nombre_cliente).includes(qNorm) || norm(c.empresa).includes(qNorm))
  .map(c => ({ phone: c.phone, nombre_cliente: c.nombre_cliente || c.phone, empresa: c.empresa || null }))
  .slice(0, 30);

return [{ json: { q, permittedPhones, phoneInfoMap, contactMatches } }];

const data = $input.first().json;
const phones = (data.permittedPhones || []).filter(p => /^[0-9]+$/.test(String(p)));
const inList = phones.length ? phones.map(p => "'" + p + "'").join(',') : 'NULL';
const query = "SELECT id, session_id, message, created_at FROM n8n_chat_histories WHERE session_id IN (" + inList + ") AND (message->>'content') ILIKE $1 ORDER BY id DESC LIMIT 100";
return [{ json: { ...data, query } }];

const rows = $input.all().map(i => i.json);
const ctx = $('Filtrar y buscar contactos').item.json;
const phoneInfoMap = ctx.phoneInfoMap || {};
const contactMatches = ctx.contactMatches || [];

const mensajes = rows
  .filter(r => r.session_id)
  .map(r => {
    let msg = r.message;
    if (typeof msg === 'string') {
      try { msg = JSON.parse(msg); } catch(e) { msg = {}; }
    }
    const info = phoneInfoMap[r.session_id] || {};
    const contenidoRaw = (msg.content || (msg.data && msg.data.content) || '')
      .replace(/\[Vendedor:[^\]]+\]\s*/, '')
      .replace(/\[IMAGEN:[^\]]+\]\s*/, '')
      .replace(/\[PHONE:[^\]]+\]\s*/, '');
    return {
      phone: r.session_id,
      mensaje_id: r.id,
      created_at: r.created_at,
      tipo: msg.type,
      contenido: contenidoRaw.slice(0, 500),
      nombre_cliente: info.nombre_cliente || r.session_id,
      empresa: info.empresa || null
    };
  })
  .filter(m => m.contenido);

return [{ json: { contactos: contactMatches, mensajes } }];

