const raw = $json || {};
let resumen = '';
if (typeof raw.mergedResponse === 'string') resumen = raw.mergedResponse;
else if (typeof raw.text === 'string') resumen = raw.text;
else if (typeof raw.response === 'string') resumen = raw.response;
else if (typeof raw.output === 'string') resumen = raw.output;
else if (Array.isArray(raw.content)) {
  resumen = raw.content.filter(c => c && c.type === 'text').map(c => c.text).join(' ');
} else if (typeof raw.content === 'string') {
  resumen = raw.content;
}
resumen = (resumen || '').trim();
if (!resumen) resumen = 'No se pudo generar el resumen automático de esta conversación.';
return [{ json: { resumen } }];

